class Solution {
  public long validSubstringCount(String word1, String word2) {
    int[] need = new int[26];
    for (int i = 0; i < word2.length(); i++) need[word2.charAt(i) - 'a']++;
    int miss = word2.length(), n = word1.length(), left = 0;
    long ans = 0;
    for (int r = 0; r < n; r++) {
      if (need[word1.charAt(r) - 'a']-- > 0) miss--;
      while (miss == 0) {
        ans += n - r;
        if (++need[word1.charAt(left++) - 'a'] > 0) miss++;
      }
    }
    return ans;
  }
}
